function bucket(capacity, ratePerSec) {
  let tokens = capacity, last = 0;
  return (t) => {
    tokens = Math.min(capacity, tokens + (t - last) * ratePerSec);
    last = t;
    if (tokens >= 1) { tokens -= 1; return true; }
    return false;
  };
}
const take = bucket(3, 1);
console.log([0, 0, 0, 0, 1.5, 1.5].map(take).join(','));

class LRU {
  constructor(cap) { this.cap = cap; this.m = new Map(); }
  get(k) {
    if (!this.m.has(k)) return undefined;
    const v = this.m.get(k);
    this.m.delete(k); this.m.set(k, v);
    return v;
  }
  set(k, v) {
    this.m.delete(k); this.m.set(k, v);
    if (this.m.size > this.cap) this.m.delete(this.m.keys().next().value);
  }
}
const c = new LRU(2);
c.set('a', 1); c.set('b', 2); c.get('a'); c.set('c', 3);
